// Proof: success UI is coupled to request acceptance, not committed state.
// Force the branch the happy path hides.
test('optimistic success must recover when validation rejects after accept', async () => {
  // Arrange: validation rejects AFTER the API has 200'd the request
  mockValidation.rejectAfterAccept({ reason: 'income_unverifiable' })

  // Act: user submits — optimistic UI shows success immediately
  const ui = await submitLoanApplication(sampleApplication)
  expect(ui.banner).toBe('Application received') // the optimistic claim

  // Assert 1: the durable truth — NO committed row
  const row = await db.loanApplications.findById(sampleApplication.id)
  expect(row).toBeNull() // DB rejected; nothing committed

  // Assert 2: the UI must recover, not strand the user on a lie
  await ui.settle()
  expect(ui.banner).toBe('We could not submit your application')
  expect(mailer.sent).toHaveLength(0) // no confirmation email on a non-commit
})

