component-boundary-mapping.code:
// Boundary checklist — one assertion per edge where trust changes:
//  [form->api]        request is validated, not trusted
//  [api->policy]      authorization decided at CREATE time
//  [policy->table]    pending invite written under tenant scope
//  [table->worker]    ASYNC edge — trust must be RE-ESTABLISHED here
//  [worker->audit]    send re-checks auth, then logs the SEND decision

test('async worker re-checks authorization before sending', async () => {
  const invite = await createInvite({ sender: 'u1', tenant: 't1' }) // passes create-time policy

  await revokeMembership('u1', 't1')        // sender loses the right BETWEEN create and send

  const sent = await runEmailWorker(invite) // the async boundary the happy path never tests

  expect(sent.status).toBe('blocked')       // FAILS today: worker trusts the stale create decision
  expect(audit.last()).toMatchObject({ edge: 'worker->send', decision: 'denied' })
})

test('replayed invite event cannot re-fire after authorization lapses', async () => {
  const evt = await createInvite({ sender: 'u1', tenant: 't1' })
  await revokeMembership('u1', 't1')
  await expect(replayEvent(evt)).rejects.toThrow('not authorized at send time')
})

