// Proof artifact: denied-action coverage for the permission editor.
// Not "can the granted user act?" — "is the WRONG user actually stopped?"
test('operator denied across tenant boundary leaves an inspectable trail', async () => {
  const op = await seedOperator({ tenant: 'acme' })
  const target = await seedResource({ tenant: 'globex' }) // different tenant

  const decision = await policyEngine.evaluate(op, 'edit', target)

  expect(decision.allowed).toBe(false)              // denial PROVEN, not assumed
  expect(decision.reason).toBe('cross_tenant_denied')

  const entry = await auditLog.latestFor(op.id)     // audit screenshot source
  expect(entry.outcome).toBe('denied')
  expect(entry.tenantFrom).toBe('acme')
  expect(entry.tenantTo).toBe('globex')

  expect(policyEvalLog.last()).toMatchObject({       // policy-eval log
    rule: 'tenant_isolation', result: 'deny', subject: op.id,
  })
})

